const copy=x=>JSON.parse(JSON.stringify(x));
function getDemo(){try{const d=JSON.parse(localStorage.getItem(STORAGE));return d&&Array.isArray(d.members)?{...copy(DEMO_START),...d}:(localDemoMemory?copy(localDemoMemory):copy(DEMO_START));}catch{return localDemoMemory?copy(localDemoMemory):copy(DEMO_START);}}
const $=id=>document.getElementById(id);
const escapeHtml=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const e=escapeHtml;
const money=n=>'RM '+(Number(n)||0).toLocaleString('ms-MY',{minimumFractionDigits:2,maximumFractionDigits:2});
const fmtDate=d=>d?new Date(String(d).length===10?d+'T12:00:00':d).toLocaleDateString('ms-MY',{day:'numeric',month:'short',year:'numeric'}):'—';
const uid=()=>globalThis.crypto?.randomUUID?.()||'demo-'+Date.now()+'-'+Math.random().toString(36).slice(2);
const opt=(items,value='')=>items.map(s=>`<option value="${e(s)}" ${s===value?'selected':''}>${e(s)}</option>`).join('');
const short=s=>String(s||'').split(' ').slice(0,2).map(x=>x[0]||'').join('').toUpperCase();
const statusBadge=s=>`<span class="badge ${['Aktif','Selesai','Diterima','Disahkan','Hadir'].includes(s)?'green':['Semakan','Dalam Semakan','Dalam Proses','Perlu Pindaan','Draf'].includes(s)?'amber':['Ditolak','Tidak Aktif'].includes(s)?'red':'blue'}">${e(s||'—')}</span>`;
const canStaff=()=>user?.status==='Aktif'&&['presiden','ajk','setiausaha','bendahari'].includes(user?.role);
const canFinance=()=>user?.status==='Aktif'&&['presiden','bendahari'].includes(user?.role);
const canReviewMembers=()=>inDemo()?canStaff():user?.status==='Aktif'&&['presiden','setiausaha'].includes(user?.role);
const isPresident=()=>user?.status==='Aktif'&&user?.role==='presiden';
const inDemo=()=>mode==='demo';
let liveStateSummary=[],liveOverview=null;
let mode='guest',authUser=null,fb=null,syncing=0,pendingReg=null,user=null,roleDemo='presiden',view='dashboard',authView='login',data=getDemo(),selectedState='Selangor',mapFilter='Aktif',memberSearch='',editDoc=null,docImages=[],modal=null,mobileOpen=false,notice='',busy=false;
const demoPerson=(role)=>role==='ahli'?data.members.find(m=>m.id==='m1')||data.members.find(m=>m.status==='Aktif'):{id:'demo-staff-'+role,full_name:LABELS[role]+' (Demo)',email:role+'@example.test',state:'Selangor',status:'Aktif',role};
function saveDemo(){if(!inDemo())return;localDemoMemory=copy(data);try{localStorage.setItem(STORAGE,JSON.stringify(data));}catch{toast('Storan browser tidak tersedia; data demo hanya dalam memori sementara.');}}
function toast(msg){const x=$('toast');if(!x)return;x.textContent=msg;x.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>x.classList.remove('show'),3600);}
function err(msg){notice=msg;render();}
function heading(title,subtitle,buttons=''){return `<div class="page-heading"><div><div class="eyebrow">MEDISTA / ${e(LABELS[user?.role]||'Portal')}</div><h1>${e(title)}</h1><p>${e(subtitle)}</p></div>${buttons?`<div class="toolbar">${buttons}</div>`:''}</div>`;}
function stat(label,num,sub){return `<div class="card"><div class="statname">${e(label)}</div><div class="statval">${e(num)}</div><div class="statfoot">${e(sub||'')}</div></div>`;}
function btn(label,action,cls=''){return `<button class="btn ${cls}" type="button" ${action}>${label}</button>`;}
const navItems=[
 ['dashboard','▦','Dashboard','all'],['members','♙','Pengurusan Ahli','staff'],['map','◉','Peta Ahli Malaysia','staff'],
 ['tasks','☑','Tugasan AJK','staff'],['reports','▤','Laporan AJK','staff'],['documents','▧','Laporan & Minit','staff'],
 ['finance','▣','Kewangan','finance'],['events','▱','Program & Kehadiran','all'],['announcements','♧','Pengumuman','all'],
 ['voting','◈','E-Voting (Pilot)','all'],['profile','☺','Profil Saya','all'],['settings','⚙','Tetapan','all']
];
function navAllowed(level){return level==='all'||level==='staff'&&canStaff()||level==='finance'&&canFinance();}
function go(id){const nav=navItems.find(n=>n[0]===id);if(!nav||!navAllowed(nav[3]))return;view=id;modal=null;editDoc=null;notice='';mobileOpen=false;render();window.scrollTo(0,0);}
function navUI(){return navItems.filter(n=>navAllowed(n[3])).map(([id,icon,label])=>`<button class="${view===id?'active':''}" data-nav="${id}" type="button"><span class="navicon">${icon}</span>${label}</button>`).join('');}
function layout(body){return `<div class="shell ${mobileOpen?'menu-open':''}"><aside class="sidebar"><div class="brandline"><img src="./icons/medista-logo.png" alt="Logo MEDISTA"><div><strong>MEDISTA</strong><small>MANAGEMENT SYSTEM</small></div></div><div class="navcap">MODUL SISTEM</div><nav class="nav">${navUI()}</nav><div class="sidebar-install">${installUI()}</div><div class="sidebar-footer">Versi 4.0 · ${inDemo()?'DEMO':'GOOGLE SHEETS'}<br>© MEDISTA</div></aside><div class="main"><header class="topbar"><div class="topbar-left"><button class="btn btn-small mobile-menu" data-menu>☰</button><span class="desktop-only">Portal MEDISTA / ${e(navItems.find(n=>n[0]===view)?.[2]||'Dashboard')}</span></div><div class="topbar-right">${!inDemo()?`<button class="btn btn-small" type="button" data-reload>↻ Muat semula</button>`:''}${inDemo()?`<span class="demo-chip">DATA DEMO</span><select id="role-demo" class="input hide-sm" style="max-width:155px;padding:7px;min-height:35px">${['presiden','setiausaha','bendahari','ajk','ahli'].map(r=>`<option value="${r}" ${roleDemo===r?'selected':''}>${e(LABELS[r])}</option>`).join('')}</select>`:''}<span class="avatar">${e(short(user?.full_name||'MD'))}</span><span class="hide-sm" style="font-size:12px;font-weight:700">${e(user?.full_name||'Ahli')}</span>${btn('Keluar','data-logout','btn-small')}</div></header><main class="content">${notice?`<div class="alert error" style="margin-bottom:16px">${e(notice)}</div>`:''}${body}<div class="footer">© MEDISTA · ${inDemo()?'Data contoh disimpan pada browser ini sahaja. Jangan guna untuk maklumat sebenar.':'Akses data dikawal melalui peranan dan polisi database.'}</div></main></div></div>${modal?modalHTML():''}`;}
function render(){const root=$('root');if(!root)return;if(mode==='guest'){root.innerHTML=authPage()+(installUI()?`<div class="install-float">${installUI()}</div>`:'');return;}
 if(!navItems.find(n=>n[0]===view&&navAllowed(n[3])))view='dashboard';
 const pages={dashboard:dashboardPage,members:membersPage,map:mapPage,tasks:tasksPage,reports:reportsPage,documents:documentsPage,finance:financePage,events:eventsPage,announcements:announcementsPage,voting:votingPage,profile:profilePage,settings:settingsPage};
 try{root.innerHTML=layout((pages[view]||dashboardPage)());}catch(ex){console.error(ex);root.innerHTML=layout(`<div class="alert error">Paparan tidak dapat dimuatkan: ${e(ex.message)}</div>`);}
}
function authPage(){const noticeBlock=notice?`<div class="alert error" style="margin:12px 0">${e(notice)}</div>`:'';
 const body=authView==='verify'?`<h2>Sahkan e-mel anda</h2><p>Pautan pengesahan telah dihantar kepada <b>${e(fb?.auth.currentUser?.email||'')}</b>. Semak juga folder spam. Selepas menekan pautan itu, kembali ke sini.</p><button class="btn btn-primary wide" type="button" data-verify-check>Saya sudah sahkan</button><div class="flex between mt"><button class="btn btn-plain" type="button" data-verify-send>Hantar semula</button><button class="btn btn-plain" type="button" data-logout>Log keluar</button></div>`:
 authView==='complete'?`<h2>Lengkapkan permohonan</h2><p>E-mel telah disahkan. Sahkan maklumat keahlian di bawah.</p><form id="complete-form" class="form-stack"><div class="field"><label>Nama penuh *</label><input class="input" name="full_name" required minlength="3" maxlength="120" value="${e(pendingReg?.full_name||'')}"></div><div class="field"><label>Telefon *</label><input class="input" name="phone" required maxlength="30" value="${e(pendingReg?.phone||'')}" placeholder="01x-xxxxxxx"></div><div class="two"><div class="field"><label>Negeri / Wilayah Persekutuan *</label><select class="input" name="state" required><option value="">Pilih negeri</option>${opt(STATES,pendingReg?.state||'')}</select></div><div class="field"><label>Jenis keahlian</label><select class="input" name="membership_type">${opt(['Biasa','Seumur Hidup'],pendingReg?.membership_type||'Biasa')}</select></div></div><label class="hint"><input type="checkbox" name="consent" required> Saya bersetuju data pendaftaran diproses untuk tujuan keahlian mengikut notis privasi MEDISTA.</label><button class="btn btn-primary wide" type="submit">Hantar permohonan</button></form><button class="btn btn-plain wide" type="button" data-logout>Log keluar</button>`:
 authView==='register'?`<h2>Daftar ahli MEDISTA</h2><p>Pilih negeri anda semasa pendaftaran. Permohonan akan disemak sebelum keahlian diaktifkan.</p><form id="register-form" class="form-stack"><div class="field"><label>Nama penuh *</label><input class="input" name="full_name" required minlength="3" maxlength="120"></div><div class="two"><div class="field"><label>E-mel *</label><input class="input" type="email" name="email" required></div><div class="field"><label>Telefon *</label><input class="input" name="phone" required maxlength="30" placeholder="01x-xxxxxxx"></div></div><div class="two"><div class="field"><label>Negeri / Wilayah Persekutuan *</label><select class="input" name="state" required><option value="">Pilih negeri</option>${opt(STATES)}</select></div><div class="field"><label>Jenis keahlian</label><select class="input" name="membership_type"><option>Biasa</option><option>Seumur Hidup</option></select></div></div><div class="field"><label>Kata laluan (12 aksara minimum) *</label><input class="input" name="password" type="password" minlength="12" autocomplete="new-password" required></div><label class="hint"><input type="checkbox" name="consent" required> Saya bersetuju data pendaftaran diproses untuk tujuan keahlian mengikut notis privasi MEDISTA.</label><button class="btn btn-primary wide" type="submit">Hantar permohonan</button></form><button class="btn btn-plain wide" data-auth="login">Sudah ada akaun? Log masuk</button>`:
 authView==='forgot'?`<h2>Set semula kata laluan</h2><p>Masukkan e-mel berdaftar untuk menerima pautan pemulihan.</p><form id="forgot-form" class="form-stack"><div class="field"><label>E-mel</label><input class="input" name="email" type="email" required></div><button class="btn btn-primary wide" type="submit">Hantar pautan</button></form><button class="btn btn-plain wide" data-auth="login">Kembali ke login</button>`:
  `<h2>Log masuk</h2><p>Akses kepada dashboard ahli, laporan AJK, program dan pengurusan MEDISTA.</p><form id="login-form" class="form-stack"><div class="field"><label>Alamat e-mel</label><input class="input" name="email" type="email" autocomplete="username" required placeholder="nama@contoh.com"></div><div class="field"><label>Kata laluan</label><input class="input" name="password" type="password" autocomplete="current-password" required></div><button class="btn btn-primary wide" type="submit" ${!DB_READY?'disabled':''}>Log masuk${!DB_READY?' (backend belum dikonfigurasi)':''}</button></form><div class="flex between mt"><button class="btn btn-plain" data-auth="register">Daftar ahli baharu</button><button class="btn btn-plain" data-auth="forgot">Lupa kata laluan?</button></div>`;
 return `<div class="auth"><section class="auth-hero"><div class="brandline"><img src="./icons/medista-logo.png" alt="Logo MEDISTA"><div><strong>MEDISTA</strong><small>Management System · PWA</small></div></div><h1>Pengurusan NGO dalam satu platform.</h1><p>Keahlian, peta negeri, laporan, minit mesyuarat, kewangan, program dan komunikasi untuk AJK serta ahli.</p><div class="auth-features"><span>✓ Satu akaun</span><span>✓ Responsif telefon</span><span>✓ Peta automatik</span><span>✓ Laporan digital</span></div></section><div class="auth-panel"><div class="auth-card">${noticeBlock}${body}${DB_READY?'':`<div style="border-top:1px solid var(--line);margin-top:23px;padding-top:15px"><div class="eyebrow">CUBA TANPA AKAUN</div><div class="two"><button class="btn btn-gold" data-demo="presiden">Demo Presiden</button><button class="btn btn-gold" data-demo="ahli">Demo Ahli</button></div><p class="hint">Mode demo hanya menyimpan data contoh pada peranti ini. Ia bukan sistem login sebenar.</p></div>`}</div></div></div>`;
}
function counts(){return {total:!inDemo()&&liveOverview?Number(liveOverview.total):data.members.length,active:!inDemo()&&liveOverview?Number(liveOverview.active):data.members.filter(m=>m.status==='Aktif').length,pending:!inDemo()&&liveOverview?Number(liveOverview.pending):data.members.filter(m=>m.status==='Semakan').length,programs:data.events.length,tasks:data.tasks.length,reports:data.reports.length};}
function dashboardPage(){const c=counts(),att=data.registrations.filter(x=>x.member_id===user?.id).length;const is=canStaff();
 let cards=is?stat('Jumlah ahli',String(c.total),'Semua status')+stat('Ahli aktif',String(c.active),'Terkira automatik mengikut negeri')+stat('Permohonan baharu',String(c.pending),'Perlu semakan AJK')+stat('Program',String(c.programs),'Program yang direkodkan'):
 stat('Status keahlian',user?.status||'—','Tertakluk kelulusan AJK')+stat('Nombor ahli',user?.member_number||'Belum diberi','Dijana selepas diluluskan')+stat('Pendaftaran program',String(att),'Program disertai')+stat('Program tersedia',String(c.programs),'Semak dan daftar');
 const pending=data.members.filter(x=>x.status==='Semakan').slice(0,4);const tasks=data.tasks.slice(0,4);
 return `${heading(is?'Dashboard Pengurusan':'Dashboard Ahli',is?'Ringkasan operasi dan pengurusan MEDISTA.':'Status keahlian, program dan berita terkini.')}${inDemo()?'<div class="alert warn" style="margin-bottom:18px">Ini ialah prototaip interaktif menggunakan data rekaan. Keputusan dan kelulusan di sini bukan rekod rasmi MEDISTA.</div>':''}<div class="grid stats">${cards}</div><div class="grid split"><div class="card"><div class="flex between wrap"><h2>${is?'Permohonan dalam semakan':'Pengumuman terkini'}</h2>${is?btn('Semua ahli','data-nav="members"','btn-small'):btn('Lihat semua','data-nav="announcements"','btn-small')}</div>${is?(pending.length?pending.map(m=>`<div class="listrow"><div><strong>${e(m.full_name)}</strong><p>${e(m.state)} · ${e(m.email)}</p></div>${statusBadge(m.status)}</div>`).join(''):'<div class="empty">Tiada permohonan menunggu kelulusan.</div>'):(data.announcements.length?data.announcements.slice(0,3).map(a=>`<div class="listrow"><div><strong>${e(a.title)}</strong><p>${e(a.body)}</p></div></div>`).join(''):'<div class="empty">Tiada pengumuman.</div>')}</div><div class="card"><h2>${is?'Tugasan & kemajuan':'Akses pantas ahli'}</h2>${is?tasks.map(t=>`<div class="listrow"><div><strong>${e(t.title)}</strong><p>${e(t.assignee_name||'AJK')} · ${fmtDate(t.due_date)}</p></div>${statusBadge(t.status)}</div>`).join(''):`<div class="list" style="margin-top:15px">${btn('Profil & negeri saya','data-nav="profile"','wide')}${btn('Daftar program','data-nav="events"','wide')}${btn('Undian percubaan','data-nav="voting"','wide')}</div>`}</div></div>${is?`<div class="card section"><div class="flex between wrap"><h2>Peta Ahli Malaysia</h2>${btn('Buka peta penuh','data-nav="map"','btn-small')}</div>${mapSVG(true)}<p class="hint">Peta visual ini ialah lakaran skematik negeri. Jumlah dikira daripada negeri pada rekod keahlian.</p></div>`:''}`;
}
function membersPage(){if(!canStaff())return '<div class="alert error">Akses untuk AJK sahaja.</div>';
 const list=data.members.filter(m=>[m.full_name,m.email,m.state,m.member_number].join(' ').toLowerCase().includes(memberSearch.toLowerCase()));
 const overview=counts();
 const tools=`<input id="member-search" class="input" style="width:240px" placeholder="Cari nama / negeri / e-mel" value="${e(memberSearch)}">${btn('Eksport statistik CSV','data-export-states','btn-small')}`;
 return `${heading('Pengurusan Ahli','Semak permohonan, kelulusan dan negeri ahli. Data peta dikira terus daripada daftar ahli.',tools)}<div class="grid stats">${stat('Semua',overview.total)}${stat('Aktif',overview.active)}${stat('Dalam semakan',overview.pending)}${stat('Tidak aktif',!inDemo()&&liveOverview?Number(liveOverview.inactive):data.members.filter(m=>m.status==='Tidak Aktif').length)}</div><div class="card">${!inDemo()?' <p class="hint">Data dibaca terus daripada Google Sheets. Kelulusan permohonan oleh Presiden atau Setiausaha.</p>':''}<div class="table-scroll"><table class="table"><thead><tr><th>Ahli</th><th>Negeri</th><th>Status</th><th>ID Ahli</th><th>Tindakan</th></tr></thead><tbody>${list.map(m=>`<tr><td><b>${e(m.full_name)}</b><br><span class="muted">${e(m.email)}</span></td><td>${e(m.state)}</td><td>${statusBadge(m.status)}</td><td>${e(m.member_number||'—')}</td><td>${m.status==='Semakan'&&canReviewMembers()?`${btn('Lulus',`data-member-review="${e(m.id)}" data-decision="Aktif"`,'btn-small btn-primary')} ${btn('Tolak',`data-member-review="${e(m.id)}" data-decision="Ditolak"`,'btn-small btn-danger')}`:'—'}</td></tr>`).join('')||'<tr><td colspan="5">Tiada rekod.</td></tr>'}</tbody></table></div></div>`;
}
function stateCounts(){const map=Object.fromEntries(STATES.map(s=>[s,0]));if(!inDemo()&&liveStateSummary.length){for(const row of liveStateSummary){if(mapFilter!=='Semua'&&row.member_status!==mapFilter)continue;if(Object.hasOwn(map,row.state_name))map[row.state_name]+=Number(row.total)||0;}return map;}for(const m of data.members){if(!STATES.includes(m.state))continue;if(mapFilter!=='Semua'&&m.status!==mapFilter)continue;map[m.state]++;}return map;}
function mapSVG(compact=false){const counts=stateCounts(),max=Math.max(1,...Object.values(counts));const points=window.MAP_SHAPES||{},pins=window.MAP_PINS||{};const polygons=Object.entries(points).map(([state,poly])=>{const n=counts[state],intensity=n/max,color=n===0?'#e8e3ee':intensity>.67?'#633b89':intensity>.33?'#986fb2':'#d5c1e4';const isSelected=selectedState===state;return `<polygon class="state-shape" points="${poly}" data-state="${e(state)}" fill="${color}" ${isSelected?'stroke="#c99b36" stroke-width="4"':''}><title>${e(state)}: ${n} ahli</title></polygon>`;}).join('');const dots=Object.entries(pins).map(([state,coords])=>`<g class="pin" data-state="${e(state)}"><circle cx="${coords[0]}" cy="${coords[1]}" r="${selectedState===state?8:6}" fill="#b68840"><title>${e(state)}: ${counts[state]} ahli</title></circle></g>`).join('');
 return `<svg class="map-svg" viewBox="95 60 900 540" role="img" aria-label="Peta skematik Malaysia dengan bilangan ahli mengikut negeri"><text x="165" y="77" font-size="18" font-weight="700" fill="#6d5d7a">SEMENANJUNG</text><text x="658" y="230" font-size="18" font-weight="700" fill="#6d5d7a">BORNEO</text>${polygons}${dots}${!compact?`<text x="150" y="573" font-size="17" fill="#8b8294">Klik negeri untuk butiran.</text>`:''}</svg>`;
}
function mapPage(){const counts=stateCounts(),all=Object.values(counts).reduce((a,b)=>a+b,0),rank=Object.entries(counts).sort((a,b)=>b[1]-a[1]),n=counts[selectedState]||0;
 return `${heading('Peta Ahli Mengikut Negeri','Statistik automatik berdasarkan negeri yang dipilih semasa pendaftaran. Tiada fail CSV diperlukan.',`<select id="map-filter" class="input">${opt(['Aktif','Semakan','Tidak Aktif','Ditolak','Semua'],mapFilter)}</select>${btn('Eksport CSV','data-export-states','btn-small')}`)}<div class="grid stats">${stat('Ahli ditapis',all)}${stat('Negeri berdaftar',rank.filter(x=>x[1]).length+' / 16')}${stat('Negeri dipilih',selectedState)}${stat('Jumlah negeri dipilih',n)}</div><div class="card"><div class="map-flex"><div>${mapSVG()}</div><div><h3>${e(selectedState)}</h3><div class="statval">${n} <span class="muted" style="font-size:16px">ahli</span></div><p class="hint">${all?Math.round(n/all*100):0}% daripada jumlah yang ditapis</p><hr style="border:0;border-top:1px solid var(--line);margin:19px 0"><h3>Ranking negeri</h3><div style="max-height:370px;overflow:auto">${rank.map(([s,c],i)=>`<button class="state-rank" data-state="${e(s)}" style="width:100%;background:none;border:0;text-align:left;cursor:pointer"><span>${i+1}. ${e(s)}</span><b>${c}</b></button>`).join('')}</div></div></div><p class="hint" style="margin:16px 0 0">Peta merupakan ilustrasi geografi skematik untuk visualisasi dashboard, bukan sempadan kartografi rasmi. WP Kuala Lumpur, Putrajaya dan Labuan dikira secara berasingan.</p></div>`;
}
function tasksPage(){const rows=data.tasks.slice().sort((a,b)=>String(a.due_date).localeCompare(String(b.due_date)));
 return `${heading('Tugasan AJK','Wujudkan tugasan, pemilik dan tarikh akhir; kemas kini perkembangan.',btn('＋ Tugasan baharu','data-open="task"','btn-primary'))}<div class="grid stats">${stat('Jumlah tugasan',rows.length)}${stat('Belum mula',rows.filter(t=>t.status==='Belum Mula').length)}${stat('Dalam proses',rows.filter(t=>t.status==='Dalam Proses').length)}${stat('Selesai',rows.filter(t=>t.status==='Selesai').length)}</div><div class="card"><div class="table-scroll"><table class="table"><thead><tr><th>Tugasan</th><th>Pemilik</th><th>Tarikh akhir</th><th>Status</th><th>Tindakan</th></tr></thead><tbody>${rows.map(t=>`<tr><td><b>${e(t.title)}</b><br><span class="muted">${e(t.description||'')}</span></td><td>${e(t.assignee_name||'AJK')}</td><td>${fmtDate(t.due_date)}</td><td>${statusBadge(t.status)}</td><td>${btn(t.status==='Selesai'?'Buka semula':'Tanda selesai',`data-task-toggle="${e(t.id)}"`,'btn-small')}</td></tr>`).join('')||'<tr><td colspan="5">Tiada tugasan.</td></tr>'}</tbody></table></div></div>`;
}
function reportsPage(){const reports=data.reports.slice().sort((a,b)=>String(b.created_at).localeCompare(String(a.created_at)));
 return `${heading('Laporan Berkala AJK','Laporan mingguan atau bulanan dengan ringkasan, isu dan rancangan seterusnya.',btn('＋ Hantar laporan','data-open="report"','btn-primary'))}<div class="grid stats">${stat('Laporan dihantar',reports.length)}${stat('Dalam semakan',reports.filter(x=>x.status==='Dalam Semakan').length)}${stat('Diterima',reports.filter(x=>x.status==='Diterima').length)}${stat('Perlu pindaan',reports.filter(x=>x.status==='Perlu Pindaan').length)}</div><div class="card"><div class="list">${reports.map(r=>`<div class="listrow"><div><strong>${e(r.title)}</strong><p>${e(r.period||'')} · ${e(r.author_name||'AJK')}</p><p>${e(r.summary||'')}</p>${r.review_note?`<p style="color:#9c6b20">Ulasan: ${e(r.review_note)}</p>`:''}</div><div class="toolbar">${statusBadge(r.status)}${isPresident()&&r.status==='Dalam Semakan'?`${btn('Terima',`data-review-report="${e(r.id)}" data-decision="Diterima"`,'btn-small btn-primary')}${btn('Pinda',`data-review-report="${e(r.id)}" data-decision="Perlu Pindaan"`,'btn-small')}`:''}</div></div>`).join('')||'<div class="empty">Belum ada laporan AJK.</div>'}</div></div>`;
}
function docTitle(d){return (d.payload?.fields?.programTitle||d.payload?.fields?.meetingSubject||d.title||'Dokumen tanpa tajuk');}
function documentsPage(){if(editDoc)return documentEditor();return `${heading('Laporan Program & Minit Mesyuarat','Borang digital berdasarkan template AMILIN. Eksport Word DOCX dan simpan PDF melalui cetakan.',`<button class="btn btn-primary" data-doc-new="program">＋ Laporan Program</button><button class="btn" data-doc-new="minutes">＋ Minit Mesyuarat</button>`)}<div class="grid stats">${stat('Jumlah dokumen',data.documents.length)}${stat('Draf',data.documents.filter(x=>x.status==='Draf').length)}${stat('Dalam semakan',data.documents.filter(x=>x.status==='Dalam Semakan').length)}${stat('Disahkan',data.documents.filter(x=>x.status==='Disahkan').length)}</div><div class="card"><div class="list">${data.documents.slice().sort((a,b)=>String(b.created_at).localeCompare(String(a.created_at))).map(d=>`<div class="listrow"><div><strong>${e(docTitle(d))}</strong><p>${d.kind==='program'?'Laporan Program':'Minit Mesyuarat'} · ${fmtDate(d.created_at)}</p><p>${e(d.review_note||'')}</p></div><div class="toolbar">${statusBadge(d.status)}${d.status!=='Disahkan'?btn('Sunting',`data-doc-edit="${e(d.id)}"`,'btn-small'):''}${btn('Word',`data-doc-export="${e(d.id)}" data-format="word"`,'btn-small')}${btn('PDF',`data-doc-export="${e(d.id)}" data-format="pdf"`,'btn-small')}${isPresident()&&d.status==='Dalam Semakan'?`${btn('Sahkan',`data-doc-review="${e(d.id)}" data-decision="Disahkan"`,'btn-small btn-primary')}${btn('Minta pindaan',`data-doc-review="${e(d.id)}" data-decision="Perlu Pindaan"`,'btn-small')}`:''}</div></div>`).join('')||'<div class="empty">Belum ada dokumen. Cipta laporan program atau minit mesyuarat.</div>'}</div></div>`;}
const df=(name,title,v='',type='text')=>`<div class="field"><label>${e(title)}</label>${type==='textarea'?`<textarea class="input" name="${name}" rows="3">${e(v)}</textarea>`:`<input class="input" type="${type}" name="${name}" value="${e(v)}" ${type==='number'?'min="0"':''}>`}</div>`;
function documentEditor(){const d=data.documents.find(x=>x.id===editDoc?.id)||editDoc;const kind=d.kind;const f=d.payload?.fields||{};const imgs=d.payload?.images||[];const title=kind==='program'?'Laporan Program':'Minit Mesyuarat';
 const common=`<div class="section"><h3>Disediakan / disemak</h3><div class="two">${df('preparedBy','Nama penyedia',f.preparedBy||user?.full_name)}${df('preparedPosition','Jawatan penyedia',f.preparedPosition||LABELS[user?.role])}${df('reviewedBy','Nama penyemak',f.reviewedBy)}${df('reviewedPosition','Jawatan penyemak',f.reviewedPosition||'Presiden')}</div></div>`;
 const program=`<div class="section"><h3>1. Butiran program</h3><div class="two">${df('programTitle','Tajuk program *',f.programTitle)}${df('programDate','Tarikh program *',f.programDate,'date')}${df('programPlace','Tempat *',f.programPlace)}${df('attendance','Jumlah kehadiran',f.attendance,'number')}</div>${df('budget','Bajet program (RM)',f.budget,'number')}${df('tentative','Tentatif program',f.tentative,'textarea')}${df('issues','Permasalahan',f.issues,'textarea')}${df('improvement','Cadangan penambahbaikan',f.improvement,'textarea')}</div><div class="section"><h3>2. Lampiran gambar (maksimum 6)</h3><div class="photo-grid" id="images-preview">${Array.from({length:6},(_,i)=>imgs.filter(x=>x.kind==='photo')[i]?`<div class="photo-slot"><img src="${e(imgs.filter(x=>x.kind==='photo')[i].data||'./icons/medista-logo.png')}" alt="Gambar program ${i+1}"></div>`:`<div class="photo-slot">Gambar ${i+1}</div>`).join('')}</div><div class="field mt"><label>Pilih gambar (JPEG/PNG/WebP)</label><input class="input" type="file" id="doc-photos" accept="image/jpeg,image/png,image/webp" multiple></div><p class="hint">Imej dioptimumkan dalam browser. Untuk produksi, imej disimpan dalam private storage apabila konfigurasi database dan storage aktif.</p></div><div class="section"><h3>3. Lampiran maklum balas</h3><div class="two">${df('feedbackResponses','Bilangan responden',f.feedbackResponses,'number')}${df('feedbackAverage','Skor purata',f.feedbackAverage)}</div>${df('feedbackText','Ringkasan maklum balas',f.feedbackText,'textarea')}<div class="field"><label>Graf maklum balas (imej)</label><input class="input" type="file" id="doc-feedback" accept="image/jpeg,image/png,image/webp"></div></div>`;
 const attendees=`<div class="table-scroll"><table class="table"><thead><tr><th>Bil</th><th>Nama</th><th>Jawatan</th><th>Kehadiran</th></tr></thead><tbody>${Array.from({length:15},(_,i)=>`<tr><td>${i+1}</td><td><input class="input" name="attName${i}" value="${e(f['attName'+i]||'')}"></td><td><input class="input" name="attPosition${i}" value="${e(f['attPosition'+i]||'')}"></td><td><select class="input" name="attStatus${i}">${opt(['','Hadir','Tidak Hadir','Berwakil'],f['attStatus'+i])}</select></td></tr>`).join('')}</tbody></table></div>`;
 const minutes=`<div class="section"><h3>1. Butiran mesyuarat</h3><div class="two">${df('meetingNo','Bilangan / rujukan *',f.meetingNo)}${df('meetingDate','Tarikh *',f.meetingDate,'date')}${df('meetingTime','Masa',f.meetingTime,'time')}${df('meetingPlace','Tempat',f.meetingPlace)}</div>${df('meetingSubject','Perkara / nama mesyuarat *',f.meetingSubject)}</div><div class="section"><h3>2. Kehadiran (15 baris)</h3>${attendees}</div><div class="section"><h3>3. Agenda dan tindakan</h3>${Array.from({length:8},(_,i)=>`<div class="agenda"><h4>Agenda ${i+1}</h4>${df('agendaTitle'+i,'Perkara',f['agendaTitle'+i]||['Tazkirah','Pemberitahuan Program Terdekat','Hal-hal lain','Penutup'][i]||'')}${df('agendaNotes'+i,'Perbincangan / keputusan',f['agendaNotes'+i],'textarea')}${df('agendaAction'+i,'Tindakan / pegawai bertanggungjawab',f['agendaAction'+i])}</div>`).join('')}</div>`;
 return `${heading(title,d.id?'Sunting dokumen dan simpan sebelum semakan.':'Isi maklumat dan simpan sebagai draf atau hantar untuk semakan.',btn('← Senarai dokumen','data-doc-back'))}<div class="card"><form id="doc-form" class="form-stack"><input type="hidden" name="doc_kind" value="${kind}">${kind==='program'?program:minutes}${common}<div class="toolbar"><button class="btn" name="intent" value="Draf" type="submit">Simpan draf</button><button class="btn btn-primary" name="intent" value="Dalam Semakan" type="submit">Hantar untuk semakan</button></div></form></div>`;
}
function financePage(){const inc=data.transactions.filter(x=>x.category==='Pendapatan').reduce((n,x)=>n+Number(x.amount),0),exp=data.transactions.filter(x=>x.category==='Perbelanjaan').reduce((n,x)=>n+Number(x.amount),0);
 return `${heading('Pengurusan Kewangan','Rekod penerimaan, perbelanjaan, baki dan jejak transaksi.',btn('＋ Rekod transaksi','data-open="finance"','btn-primary'))}<div class="grid stats">${stat('Pendapatan',money(inc))}${stat('Perbelanjaan',money(exp))}${stat('Baki bersih',money(inc-exp))}${stat('Transaksi',data.transactions.length)}</div><div class="card"><div class="table-scroll"><table class="table"><thead><tr><th>Tarikh</th><th>Butiran</th><th>Jenis</th><th>Jumlah (RM)</th></tr></thead><tbody>${data.transactions.slice().sort((a,b)=>String(b.txn_date).localeCompare(String(a.txn_date))).map(x=>`<tr><td>${fmtDate(x.txn_date)}</td><td>${e(x.description)}</td><td>${statusBadge(x.category)}</td><td style="font-weight:800">${money(x.amount)}</td></tr>`).join('')||'<tr><td colspan="4">Tiada transaksi.</td></tr>'}</tbody></table></div></div><div class="alert warn mt">Rekod kewangan dalam aplikasi ialah lejar operasi ringkas, bukan sistem perakaunan beraudit. Gunakan semakan berganda dan rekonsiliasi bank sebelum pelaporan rasmi.</div>`;
}
function eventRegistered(eventId){return data.registrations.some(r=>r.event_id===eventId&&r.member_id===user?.id);}
function eventsPage(){const items=data.events.slice().sort((a,b)=>String(a.event_date).localeCompare(String(b.event_date)));
 return `${heading('Program & Aktiviti','Urus acara, pendaftaran ahli, kehadiran dan sijil penyertaan.',canStaff()?btn('＋ Program baharu','data-open="event"','btn-primary'):'')}<div class="grid feature-cards">${items.map(ev=>{const registrations=data.registrations.filter(r=>r.event_id===ev.id),reg=data.registrations.find(r=>r.event_id===ev.id&&r.member_id===user?.id);return `<div class="card"><div class="flex between"><span class="badge blue">${fmtDate(ev.event_date)}</span><span class="muted" style="font-size:12px">${registrations.length}/${e(ev.capacity||'∞')} peserta</span></div><h2 style="font-size:20px;margin-top:17px">${e(ev.name)}</h2><p class="hint">📍 ${e(ev.venue||'Belum ditetapkan')}</p><p style="font-size:13px;line-height:1.5">${e(ev.description||'')}</p><div class="toolbar mt">${reg?statusBadge(reg.attended?'Hadir':'Berdaftar'):''}${!reg&&user?.status==='Aktif'?btn('Daftar program',`data-event-register="${e(ev.id)}"`,'btn-primary'):''}${reg?.attended?btn('Cetak sijil',`data-certificate="${e(ev.id)}"`,'btn-small'):''}${canStaff()?btn('Senarai peserta',`data-event-people="${e(ev.id)}"`,'btn-small'):''}</div></div>`;}).join('')||'<div class="empty">Tiada program untuk dipaparkan.</div>'}</div>`;
}
function announcementsPage(){return `${heading('Pengumuman & Makluman','Maklumat terkini untuk AJK dan ahli.',canStaff()?btn('＋ Pengumuman','data-open="announcement"','btn-primary'):'')}<div class="grid">${data.announcements.slice().sort((a,b)=>String(b.created_at).localeCompare(String(a.created_at))).map(x=>`<div class="card"><div class="flex between"><h2>${e(x.title)}</h2><span class="hint">${fmtDate(x.created_at)}</span></div><p style="line-height:1.7;white-space:pre-wrap;font-size:14px">${e(x.body)}</p></div>`).join('')||'<div class="empty">Tiada pengumuman buat masa ini.</div>'}</div><p class="hint mt">Pengumuman dalam sistem tidak secara automatik menghantar WhatsApp/SMS. Integrasi e-mel atau WhatsApp Business memerlukan penyedia sah dan konfigurasi tambahan.</p>`;}
function votingPage(){const allowed=inDemo()||CFG.enableVotingProduction===true;
 return `${heading('E-Voting · Modul Perintis','Simulasi pencalonan dan undian sekali setiap ahli. Tidak boleh digunakan untuk pemilihan rasmi tanpa audit keselamatan.')}<div class="alert warn" style="margin-bottom:17px">${allowed?'UNDlAN PERCUBAAN — Undian ini bukan undi rasmi dan bukan sulit secara kriptografi.':'Pengundian sebenar belum diaktifkan. Modul perlu diaudit dan dipersetujui dalam perlembagaan sebelum produksi.'}</div>${data.elections.map(v=>`<div class="card" style="margin-bottom:15px"><div class="flex between wrap"><h2>${e(v.title)}</h2>${statusBadge(v.status)}</div><p class="hint">Tamat: ${fmtDate(v.ends_at)} · ${v.votes?.length||0} undi simulasi</p>${allowed&&inDemo()?`<div class="list">${v.candidates.map((c,i)=>`<button class="btn" data-vote="${e(v.id)}" data-candidate="${i}" ${v.votes.some(z=>z.member_id===user?.id)||user?.status!=='Aktif'?'disabled':''}>${e(c)}</button>`).join('')}</div>${v.votes.some(z=>z.member_id===user?.id)?'<p class="hint">Anda telah mengundi dalam demo ini.</p>':''}`:''}${isPresident()&&inDemo()?`<div class="section"><h3>Keputusan demo</h3>${v.candidates.map((c,i)=>`<p class="hint">${e(c)} — ${v.votes.filter(z=>z.candidate===i).length} undi</p>`).join('')}</div>`:''}</div>`).join('')||'<div class="empty">Tiada pilihan raya.</div>'}`;
}
function profilePage(){return `${heading('Profil Saya','Semak maklumat keahlian dan negeri bagi pengiraan automatik pada peta.')}<div class="card" style="max-width:790px"><div class="logo-banner"><img src="./icons/medista-logo.png" class="profilepic" alt="Logo MEDISTA"><div><h2 style="margin:0">${e(user?.full_name)}</h2><p class="hint">${e(user?.member_number||'Nombor ahli belum dijana')} · ${statusBadge(user?.status)}</p></div></div><form id="profile-form" class="form-stack mt"><div class="field"><label>Nama penuh</label><input class="input" name="full_name" required minlength="3" value="${e(user?.full_name||'')}"></div><div class="two"><div class="field"><label>E-mel</label><input class="input" value="${e(user?.email||'')}" disabled></div><div class="field"><label>Telefon</label><input class="input" name="phone" value="${e(user?.phone||'')}"></div></div><div class="field"><label>Negeri / Wilayah Persekutuan</label><select class="input" name="state">${opt(STATES,user?.state)}</select></div><button class="btn btn-primary" type="submit">Simpan profil & kemas kini negeri</button></form><p class="hint mt">Apabila negeri ahli aktif berubah, peta akan mengira semula statistik berdasarkan rekod terkini.</p></div>`;}
function settingsPage(){return `${heading('Tetapan Sistem','Konfigurasi, keselamatan dan maklumat mod aplikasi.')}<div class="grid feature-cards"><div class="card"><h2>Status sistem</h2><p>${statusBadge(inDemo()?'Demo LocalStorage':'Google Sheets')}</p><p class="hint">${inDemo()?'Perubahan hanya tersimpan pada browser dan tidak boleh digunakan untuk data rasmi.':'Data dikongsi mengikut peraturan akses database.'}</p>${inDemo()?btn('Set semula semua data demo','data-reset-demo','btn-danger'):''}</div><div class="card"><h2>Identiti & keselamatan</h2><p class="hint">Log masuk melalui Firebase. Peranan ditetapkan dalam tab PENGGUNA dan disemak di pelayan untuk setiap permintaan. E-voting rasmi dan automasi notifikasi masih memerlukan penilaian tambahan.</p><p class="hint">Simpan kunci rahsia hanya pada persekitaran server; jangan letak dalam config.js.</p></div><div class="card"><h2>Tarik keluar statistik</h2>${canStaff()?btn('Eksport bilangan ahli per negeri','data-export-states','btn-small'):''}<p class="hint">Fail CSV agregat tidak merangkumi nama, nombor telefon atau e-mel ahli.</p></div><div class="card"><h2>Maklumat aplikasi</h2><p class="hint">MEDISTA PWA v4.0. Responsif pada komputer dan telefon. Pemasangan PWA memerlukan HTTPS atau localhost.</p></div></div>`;}
function modalHTML(){const config={task:['Tugasan AJK Baharu',`<div class="form-stack">${df('title','Tajuk tugasan *')}${df('description','Huraian','', 'textarea')}<div class="two">${df('assignee_name','Pemilik / AJK')}${df('due_date','Tarikh akhir','', 'date')}</div><div class="field"><label>Status</label><select class="input" name="status">${opt(['Belum Mula','Dalam Proses','Selesai'])}</select></div></div>`],report:['Hantar Laporan AJK',`<div class="form-stack">${df('title','Tajuk laporan *')}<div class="field"><label>Tempoh laporan *</label><input class="input" name="period" type="month" required></div>${df('summary','Aktiviti / pencapaian *','','textarea')}${df('challenges','Isu atau masalah','','textarea')}${df('next_steps','Tindakan susulan','','textarea')}</div>`],finance:['Rekod Transaksi',`<div class="form-stack">${df('txn_date','Tarikh *',new Date().toISOString().slice(0,10),'date')}${df('description','Butiran transaksi *')}<div class="two"><div class="field"><label>Jenis</label><select class="input" name="category">${opt(['Pendapatan','Perbelanjaan'])}</select></div>${df('amount','Jumlah (RM) *','', 'number')}</div></div>`],event:['Program Baharu',`<div class="form-stack">${df('name','Nama program *')}${df('description','Penerangan','','textarea')}<div class="two">${df('event_date','Tarikh *','','date')}${df('venue','Tempat *')}</div>${df('capacity','Kapasiti maksimum','100','number')}</div>`],announcement:['Pengumuman Baharu',`<div class="form-stack">${df('title','Tajuk pengumuman *')}${df('body','Maklumat / teks *','','textarea')}</div>`]};
 if(modal.type==='people'){const ev=data.events.find(x=>x.id===modal.id),regs=data.registrations.filter(r=>r.event_id===modal.id);return `<div class="modal-bg" data-modalback><div class="modal"><div class="modal-top"><h2>Senarai peserta · ${e(ev?.name||'')}</h2>${btn('✕','data-close','btn-small')}</div>${regs.length?`<div class="table-scroll"><table class="table"><thead><tr><th>Ahli</th><th>Kod</th><th>Status</th><th>Tindakan</th></tr></thead><tbody>${regs.map(r=>{const m=data.members.find(x=>x.id===r.member_id);return `<tr><td>${e(m?.full_name||r.member_id)}</td><td>${e(String(r.id).slice(0,8).toUpperCase())}</td><td>${statusBadge(r.attended?'Hadir':'Berdaftar')}</td><td>${!r.attended?btn('Tandakan hadir',`data-checkin="${e(r.id)}"`,'btn-small btn-primary'):'—'}</td></tr>`}).join('')}</tbody></table></div>`:'<div class="empty">Belum ada pendaftaran.</div>'}</div></div>`;}
 const item=config[modal.type];if(!item)return '';return `<div class="modal-bg" data-modalback><div class="modal" style="max-width:680px"><div class="modal-top"><h2>${item[0]}</h2>${btn('✕','data-close','btn-small')}</div><form id="modal-form" data-kind="${e(modal.type)}" class="form-stack">${item[1]}<div class="toolbar mt"><button class="btn btn-primary" type="submit">Simpan ${modal.type==='report'?'& hantar untuk semakan':''}</button><button class="btn" type="button" data-close>Batal</button></div></form></div></div>`;}
function getForm(form){return Object.fromEntries(Array.from(new FormData(form),([k,v])=>[k,typeof v==='string'?v.trim():v]));}
async function handleSave(table,record){if(inDemo()){const key=table==='finance_transactions'?'transactions':table==='event_registrations'?'registrations':table;if(!data[key])throw Error('Modul tidak dikenali.');data[key].unshift(record);saveDemo();return record;}
 return api('createRecord',{table,record});}
async function handleUpdate(table,id,update){if(inDemo()){const key=table==='finance_transactions'?'transactions':table==='event_registrations'?'registrations':table;const row=data[key].find(x=>x.id===id);if(!row)throw Error('Rekod tidak ditemui.');Object.assign(row,update);saveDemo();return row;}
 if(table==='tasks')return api('updateTask',{id,status:update.status});throw Error('Tindakan tidak disokong.');}
function download(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),12000);}
function exportStates(){const counts=stateCounts(),csv='negeri,jumlah,status\n'+STATES.map(s=>`"${s}",${counts[s]},"${mapFilter}"`).join('\n');download(new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8'}),'MEDISTA_Taburan_Ahli_Negeri.csv');}
async function fileImage(file){if(!/^image\/(jpeg|png|webp)$/.test(file.type))throw Error('Jenis gambar tidak dibenarkan.');if(file.size>12*1024*1024)throw Error('Gambar maksimum 12MB sebelum dimampatkan.');
 const image=await new Promise((resolve,reject)=>{const img=new Image(),url=URL.createObjectURL(file);img.onload=()=>{URL.revokeObjectURL(url);resolve(img)};img.onerror=()=>{URL.revokeObjectURL(url);reject(Error('Gagal membaca gambar'))};img.src=url;});
 const scale=Math.min(1,1000/Math.max(image.naturalWidth,image.naturalHeight)),canvas=document.createElement('canvas');canvas.width=Math.round(image.naturalWidth*scale);canvas.height=Math.round(image.naturalHeight*scale);const ctx=canvas.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(image,0,0,canvas.width,canvas.height);return {data:canvas.toDataURL('image/jpeg',.76),width:canvas.width,height:canvas.height,name:file.name};}
async function storeDocImages(docId,images){if(inDemo())return images;
 let out=[];for(const im of images){if(!im.data){out.push(im);continue;}const r=await api('uploadImage',{base64:String(im.data).split(',')[1]});out.push({kind:im.kind,name:im.name,width:im.width,height:im.height,path:r.path});}return out;}
async function exportDoc(id,format){const row=data.documents.find(d=>d.id===id);if(!row)return;const doc={id:row.id,kind:row.kind,status:row.status,fields:row.payload?.fields||{},images:copy(row.payload?.images||[])};
 for(const item of doc.images){if(item.path&&!item.data){const r=await api('getImage',{path:item.path});item.data='data:image/jpeg;base64,'+r.base64;}}
 if(format==='word')downloadWord(doc);else printDocument(doc);}
function printCertificate(ev,reg){const safeName=e(user?.full_name||'Ahli'),safeEvent=e(ev.name);const html=`<!doctype html><html lang="ms"><head><meta charset="utf-8"><title>Sijil MEDISTA</title><style>@page{size:A4 landscape;margin:15mm}body{font:20px Georgia,serif;padding:55px;border:14px solid #48246b;text-align:center;min-height:400px;color:#352249}img{height:95px}h1{font-size:40px;color:#46236D}b{font-size:30px}.detail{margin:30px}small{font:14px Arial}</style></head><body><img src="${MEDISTA_LOGO_DATA}" alt="Logo"><h1>SIJIL PENYERTAAN</h1><p>Dengan ini disahkan bahawa</p><div class="detail"><b>${safeName}</b></div><p>telah hadir dan menyertai</p><h2>${safeEvent}</h2><p>${e(fmtDate(ev.event_date))} · ${e(ev.venue)}</p><small>No. rujukan: ${e(String(reg.id).slice(0,8))} · Sijil dijana berdasarkan rekod kehadiran sistem</small><script>onload=()=>setTimeout(()=>print(),300)<\/script></body></html>`;const win=window.open('','_blank');if(win){win.document.write(html);win.document.close();}else download(new Blob([html],{type:'text/html'}),'sijil-medista.html');}
async function runAction(fn){if(busy)return;busy=true;try{await fn();render();}catch(ex){console.error(ex);notice=ex.message||'Ralat sistem';render();}finally{busy=false;}}
async function saveModal(form){const values=getForm(form),kind=form.dataset.kind;const common={id:uid(),created_at:new Date().toISOString(),created_by:user.id};
 if(kind==='task'){if(!values.title)throw Error('Masukkan tajuk tugasan.');await handleSave('tasks',{...common,title:values.title,description:values.description||'',assignee_name:values.assignee_name||'',due_date:values.due_date||null,status:values.status||'Belum Mula'});}
 if(kind==='report'){if(!values.title||!values.period||!values.summary)throw Error('Lengkapkan tajuk, tempoh dan ringkasan.');await handleSave('reports',{...common,title:values.title,period:values.period,summary:values.summary,challenges:values.challenges,next_steps:values.next_steps,status:'Dalam Semakan',author_name:user.full_name});}
 if(kind==='finance'){const amount=Number(values.amount);if(!values.description||!values.txn_date||!Number.isFinite(amount)||amount<=0)throw Error('Sila isi transaksi dengan jumlah positif.');await handleSave('finance_transactions',{...common,txn_date:values.txn_date,description:values.description,category:values.category,amount});}
 if(kind==='event'){if(!values.name||!values.event_date||!values.venue)throw Error('Lengkapkan maklumat program.');await handleSave('events',{...common,name:values.name,description:values.description,venue:values.venue,event_date:values.event_date,capacity:Math.max(1,Number(values.capacity)||100)});}
 if(kind==='announcement'){if(!values.title||!values.body)throw Error('Isi tajuk dan pengumuman.');await handleSave('announcements',{...common,title:values.title,body:values.body});}
 modal=null;if(!inDemo())await loadAll();toast('Rekod berjaya disimpan.');}
async function saveDocument(form,submitter){const kind=editDoc.kind,f=getForm(form),status=submitter?.value==='Dalam Semakan'?'Dalam Semakan':'Draf';const required=kind==='program'?['programTitle','programDate','programPlace']:['meetingNo','meetingDate','meetingSubject'];if(status==='Dalam Semakan'&&required.some(k=>!f[k]))throw Error('Lengkapkan semua butiran bertanda * sebelum menghantar.');
 let id=editDoc.id||uid(),payload={fields:f,images:await storeDocImages(id,docImages)};
 let row={id,kind,title:kind==='program'?f.programTitle||'Draf laporan program':f.meetingSubject||'Draf minit mesyuarat',status,payload,updated_at:new Date().toISOString()};
 if(inDemo()){const existing=data.documents.find(x=>x.id===id);if(existing){if(existing.status==='Disahkan')throw Error('Dokumen telah disahkan dan tidak boleh diubah.');Object.assign(existing,row);}else data.documents.unshift({...row,created_at:new Date().toISOString(),author_id:user.id});saveDemo();}
 else{await api('saveDocument',{id:editDoc.id||null,kind,title:row.title,status,payload});await loadAll();}
 editDoc=null;docImages=[];toast(status==='Draf'?'Draf disimpan.':'Dokumen dihantar untuk semakan.');}
async function reviewMember(id,decision){if(!confirm(`Sahkan ${decision==='Aktif'?'kelulusan':'penolakan'} permohonan ini?`))return;
 if(inDemo()){const m=data.members.find(x=>x.id===id);if(!m||m.status!=='Semakan')throw Error('Permohonan sudah diproses.');m.status=decision;if(decision==='Aktif')m.member_number='MED-'+String(100+data.members.length+Math.floor(Math.random()*100)).padStart(6,'0');saveDemo();}
 else{await api('reviewMember',{id,decision});await loadAll();}
 toast('Status permohonan dikemas kini.');}
async function reviewReport(id,decision){if(!isPresident())throw Error('Hanya Presiden boleh menyemak laporan.');let note='';if(decision==='Perlu Pindaan'){note=prompt('Catatan pindaan:')||'';if(!note)return;}
 if(inDemo())await handleUpdate('reports',id,{status:decision,review_note:note});else{await api('reviewReport',{id,decision,note});await loadAll();}toast('Laporan disemak.');}
async function reviewDocument(id,decision){if(!isPresident())throw Error('Hanya Presiden boleh menyemak dokumen.');let note='';if(decision==='Perlu Pindaan'){note=prompt('Ulasan pindaan:')||'';if(!note)return;}
 if(inDemo())await handleUpdate('documents',id,{status:decision,review_note:note});else{await api('reviewDocument',{id,decision,note});await loadAll();}toast('Semakan dokumen disimpan.');}
async function registerEvent(id){if(user?.status!=='Aktif')throw Error('Pendaftaran program untuk ahli aktif sahaja.');if(eventRegistered(id))throw Error('Anda telah mendaftar.');
 if(inDemo()){const ev=data.events.find(x=>x.id===id);const total=data.registrations.filter(x=>x.event_id===id).length;if(ev?.capacity&&total>=ev.capacity)throw Error('Kapasiti program penuh.');await handleSave('event_registrations',{id:uid(),event_id:id,member_id:user.id,attended:false});}
 else{await api('registerEvent',{id});await loadAll();}toast('Pendaftaran program berjaya.');}
async function checkIn(id){if(!canStaff())throw Error('Akses hanya AJK.');const r=data.registrations.find(x=>x.id===id);if(!r)throw Error('Pendaftaran tidak ditemui.');if(inDemo())await handleUpdate('event_registrations',id,{attended:true});else{await api('checkIn',{id});await loadAll();}toast('Kehadiran telah direkod.');}
async function updateProfile(form){let f=getForm(form);if(f.full_name.length<3||!STATES.includes(f.state))throw Error('Nama dan negeri wajib sah.');if(inDemo()){Object.assign(user,{full_name:f.full_name,phone:f.phone,state:f.state});const m=data.members.find(x=>x.id===user.id);if(m)Object.assign(m,user);saveDemo();}
 else{await api('updateProfile',{full_name:f.full_name,phone:f.phone,state:f.state});await loadAll();}toast('Profil dan negeri telah dikemas kini.');}
function demoEnter(role){data=getDemo();roleDemo=role;user=copy(demoPerson(role));mode='demo';view='dashboard';notice='';render();}
async function logOut(){if(inDemo()){mode='guest';user=null;view='dashboard';authView='login';render();return;}await fb?.signOut(fb.auth);authUser=null;user=null;mode='guest';view='dashboard';authView='login';render();}
/* Lapisan API: Firebase ID token -> Apps Script -> Google Sheets. text/plain mengelakkan CORS preflight yang tidak disokong Apps Script. */
function setSync(d){syncing=Math.max(0,syncing+d);document.body.classList.toggle('syncing',syncing>0);}
async function api(action,payload={}){const u=fb?.auth.currentUser;if(!u)throw Error('Sila log masuk semula.');if(!navigator.onLine)throw Error('Tiada sambungan internet. Data tidak disimpan.');setSync(1);try{const idToken=await u.getIdToken();let r;try{r=await fetch(CFG.apiUrl,{method:'POST',headers:{'Content-Type':'text/plain;charset=utf-8'},redirect:'follow',body:JSON.stringify({idToken,action,data:payload})});}catch{throw Error('Tidak dapat menghubungi pelayan MEDISTA. Cuba lagi.');}let j;try{j=await r.json();}catch{throw Error('Pelayan MEDISTA memberi jawapan tidak sah.');}if(!j.ok)throw Error(j.error||'Permintaan gagal.');return j.result;}finally{setSync(-1);}}
async function loadAll(){if(mode!=='live')return;const r=await api('bootstrap');if(!r.registered){mode='guest';user=null;authView='complete';return;}applyBootstrap(r);}
function applyBootstrap(r){user=r.member;liveStateSummary=r.stateSummary||[];liveOverview=r.overview||null;data={...copy(DEMO_START),members:r.members||[user],tasks:r.tasks||[],reports:r.reports||[],documents:r.documents||[],events:r.events||[],registrations:r.registrations||[],transactions:r.transactions||[],announcements:r.announcements||[],elections:[]};}
async function afterSignIn(){const u=fb.auth.currentUser;if(!u){mode='guest';return;}await u.reload();authUser=u;if(!u.emailVerified){authView='verify';mode='guest';return;}const r=await api('bootstrap');if(!r.registered){try{pendingReg=JSON.parse(localStorage.getItem('medista-pending-reg')||'null');}catch{pendingReg=null;}authView='complete';mode='guest';notice='';return;}try{localStorage.removeItem('medista-pending-reg');}catch{}mode='live';applyBootstrap(r);view='dashboard';notice='';}
const FB_ERRORS={'auth/invalid-credential':'E-mel atau kata laluan tidak betul.','auth/wrong-password':'E-mel atau kata laluan tidak betul.','auth/user-not-found':'E-mel atau kata laluan tidak betul.','auth/invalid-email':'Format e-mel tidak sah.','auth/email-already-in-use':'E-mel ini sudah berdaftar. Sila log masuk.','auth/weak-password':'Kata laluan terlalu lemah.','auth/too-many-requests':'Terlalu banyak percubaan. Cuba lagi sebentar.','auth/network-request-failed':'Tiada sambungan internet.','auth/unauthorized-domain':'Domain ini belum dibenarkan dalam Firebase.','auth/unauthorized-continue-uri':'Domain ini belum dibenarkan dalam Firebase.'};
const fbMsg=ex=>FB_ERRORS[ex?.code]||ex?.message||'Ralat sistem';
async function authSubmit(form){const f=getForm(form);busy=true;try{
 if(form.id==='register-form'){
  if(!f.full_name||!STATES.includes(f.state)||!f.email||!f.consent||f.password.length<12)throw Error('Lengkapkan semua maklumat. Kata laluan minimum 12 aksara.');
  if(!DB_READY){const id=uid();data=getDemo();data.members.unshift({id,full_name:f.full_name,email:f.email,phone:f.phone,state:f.state,membership_type:f.membership_type,role:'ahli',status:'Semakan',created_at:new Date().toISOString()});localDemoMemory=copy(data);try{localStorage.setItem(STORAGE,JSON.stringify(data));}catch{}authView='login';notice='Permohonan DEMO disimpan pada browser ini. Untuk akaun sebenar, pentadbir perlu mengaktifkan backend. Tiada kata laluan disimpan.';render();return;}
  if(!fb)throw Error('Sambungan log masuk belum sedia. Semak internet dan muat semula.');
  try{localStorage.setItem('medista-pending-reg',JSON.stringify({full_name:f.full_name,phone:f.phone,state:f.state,membership_type:f.membership_type}));}catch{}
  const cred=await fb.createUserWithEmailAndPassword(fb.auth,f.email,f.password);await fb.sendEmailVerification(cred.user);authUser=cred.user;authView='verify';notice='';render();return;
 }
 if(!fb)throw Error('Sambungan log masuk belum sedia. Semak internet dan muat semula.');
 if(form.id==='login-form'){await fb.signInWithEmailAndPassword(fb.auth,f.email,f.password);await afterSignIn();render();return;}
 if(form.id==='forgot-form'){await fb.sendPasswordResetEmail(fb.auth,f.email).catch(ex=>{if(ex.code!=='auth/user-not-found')throw ex;});authView='login';notice='Jika e-mel berdaftar, pautan pemulihan akan dihantar.';render();return;}
 if(form.id==='complete-form'){if(!f.full_name||!STATES.includes(f.state)||!f.consent)throw Error('Lengkapkan semua maklumat.');await api('registerMember',{name:f.full_name,phone:f.phone,state:f.state,category:f.membership_type,consent:true});pendingReg=null;await afterSignIn();render();return;}
 }catch(ex){notice=fbMsg(ex);render();}finally{busy=false;}}
/* Firebase dimuat hanya bila backend dikonfigurasi, supaya mod demo tiada pergantungan rangkaian. */
async function loadFirebase(){const v='https://www.gstatic.com/firebasejs/13.1.0/';const [a,m]=await Promise.all([import(v+'firebase-app.js'),import(v+'firebase-auth.js')]);fb={...m,auth:m.getAuth(a.initializeApp(CFG.firebase))};await fb.auth.authStateReady();}
/* Pemasangan PWA */
let installEvt=null;
function isStandalone(){return matchMedia('(display-mode: standalone)').matches||navigator.standalone===true;}
function isIOS(){return /iphone|ipad|ipod/i.test(navigator.userAgent)||(navigator.platform==='MacIntel'&&navigator.maxTouchPoints>1);}
function canHostInstall(){return location.protocol==='https:'||location.hostname==='localhost';}
function installUI(){if(isStandalone()||!canHostInstall())return '';
 if(installEvt)return `<div class="install-box"><div><strong>Pasang MEDISTA</strong><small>Buka seperti aplikasi, terus dari skrin utama.</small></div><button class="btn btn-primary btn-small" type="button" data-install>Pasang</button></div>`;
 if(isIOS())return `<div class="install-box"><div><strong>Pasang di iPhone/iPad</strong><small>Dalam Safari, tekan Kongsi, kemudian “Add to Home Screen”.</small></div></div>`;
 return '';}
window.addEventListener('beforeinstallprompt',ev=>{ev.preventDefault();installEvt=ev;render();});
window.addEventListener('appinstalled',()=>{installEvt=null;render();toast('MEDISTA telah dipasang.');});
async function init(){if('serviceWorker' in navigator&&(location.protocol==='https:'||location.hostname==='localhost'))navigator.serviceWorker.register('./sw.js').catch(console.warn);
 if(DB_READY){try{await loadFirebase();if(fb.auth.currentUser)await afterSignIn();}catch(ex){console.error(ex);mode='guest';notice=navigator.onLine?fbMsg(ex):'Tiada sambungan internet. Sambung dan muat semula untuk log masuk.';}}
 render();}

document.addEventListener('click',ev=>{const b=ev.target.closest('button,[data-state]');if(!b)return;const a=b.dataset;
 if(a.install!==undefined){if(installEvt){const ev=installEvt;installEvt=null;ev.prompt();ev.userChoice.finally(()=>render());}return;}
 if(a.reload!==undefined){runAction(async()=>{await loadAll();toast('Data dikemas kini.');});return;}
 if(a.verifyCheck!==undefined){runAction(async()=>{notice='';await afterSignIn();if(authView==='verify')notice='E-mel belum disahkan. Tekan pautan dalam e-mel dahulu.';});return;}
 if(a.verifySend!==undefined){runAction(async()=>{try{await fb.sendEmailVerification(fb.auth.currentUser);toast('Pautan dihantar semula.');}catch(ex){throw Error(fbMsg(ex));}});return;}
 if(a.auth){authView=a.auth;notice='';render();return;}if(a.demo){demoEnter(a.demo);return;}
 if(a.nav){go(a.nav);return;}if(a.menu!==undefined){mobileOpen=!mobileOpen;render();return;}
 if(a.logout!==undefined){runAction(logOut);return;}
 if(a.open){if(!canStaff()||a.open==='finance'&&!canFinance())return;modal={type:a.open};render();return;}
 if(a.close!==undefined){modal=null;render();return;}
 if(a.state){selectedState=a.state;render();return;}
 if(a.exportStates!==undefined){exportStates();return;}
 if(a.resetDemo!==undefined){if(inDemo()&&confirm('Reset semua perubahan data demo pada browser?')){try{localStorage.removeItem(STORAGE);}catch{}localDemoMemory=null;data=getDemo();user=copy(demoPerson(roleDemo));render();toast('Data demo dipulihkan.');}return;}
 if(a.memberReview){runAction(()=>reviewMember(a.memberReview,a.decision));return;}
 if(a.taskToggle){runAction(async()=>{const t=data.tasks.find(x=>x.id===a.taskToggle);if(!t)return;await handleUpdate('tasks',t.id,{status:t.status==='Selesai'?'Dalam Proses':'Selesai'});if(!inDemo())await loadAll();toast('Status tugasan dikemas kini.');});return;}
 if(a.reviewReport){runAction(()=>reviewReport(a.reviewReport,a.decision));return;}
 if(a.docNew){editDoc={kind:a.docNew,id:null,payload:{fields:{},images:[]}};docImages=[];render();return;}
 if(a.docBack!==undefined){editDoc=null;docImages=[];render();return;}
 if(a.docEdit){const d=data.documents.find(x=>x.id===a.docEdit);if(!d)return;editDoc=copy(d);docImages=copy(d.payload?.images||[]);render();return;}
 if(a.docExport){runAction(()=>exportDoc(a.docExport,a.format));return;}
 if(a.docReview){runAction(()=>reviewDocument(a.docReview,a.decision));return;}
 if(a.eventRegister){runAction(()=>registerEvent(a.eventRegister));return;}
 if(a.eventPeople){modal={type:'people',id:a.eventPeople};render();return;}
 if(a.checkin){runAction(()=>checkIn(a.checkin));return;}
 if(a.certificate){const evRow=data.events.find(x=>x.id===a.certificate),reg=data.registrations.find(x=>x.event_id===a.certificate&&x.member_id===user?.id);if(evRow&&reg?.attended)printCertificate(evRow,reg);return;}
 if(a.vote){if(!inDemo()||user?.status!=='Aktif')return;const election=data.elections.find(x=>x.id===a.vote);if(!election||election.votes.some(x=>x.member_id===user.id))return;const index=Number(a.candidate);if(!Number.isInteger(index)||!election.candidates[index])return;if(confirm('Hantar undi percubaan untuk '+election.candidates[index]+'?')){election.votes.push({member_id:user.id,candidate:index});saveDemo();render();toast('Undi demo direkod.');}return;}
});
document.addEventListener('change',ev=>{const t=ev.target;if(t.id==='role-demo'){if(inDemo()){roleDemo=t.value;user=copy(demoPerson(roleDemo));view='dashboard';render();}return;}
 if(t.id==='map-filter'){mapFilter=t.value;render();return;}
 if(t.id==='doc-photos'||t.id==='doc-feedback'){const kind=t.id==='doc-photos'?'photo':'feedback';const files=Array.from(t.files||[]);(async()=>{try{if(kind==='photo'&&docImages.filter(x=>x.kind==='photo').length+files.length>6)throw Error('Maksimum 6 gambar program.');for(const file of files){const im=await fileImage(file);if(kind==='feedback')docImages=docImages.filter(x=>x.kind!=='feedback');docImages.push({...im,kind});}
  const msg=kind==='photo'?`${docImages.filter(x=>x.kind==='photo').length} gambar disediakan untuk simpanan`:'Graf maklum balas disediakan';toast(msg);const prev=$('images-preview');if(prev){const pictures=docImages.filter(x=>x.kind==='photo');prev.innerHTML=Array.from({length:6},(_,i)=>pictures[i]?`<div class="photo-slot">${pictures[i].data?`<img src="${pictures[i].data}" alt="Gambar ${i+1}">`:`<span>${e(pictures[i].name)}</span>`}</div>`:`<div class="photo-slot">Gambar ${i+1}</div>`).join('');}
 }catch(ex){toast(ex.message);}})();return;}
});
document.addEventListener('input',ev=>{if(ev.target.id==='member-search'){memberSearch=ev.target.value;const selection=ev.target.selectionStart;render();const input=$('member-search');input?.focus();input?.setSelectionRange(selection,selection);}});
document.addEventListener('submit',ev=>{const form=ev.target;if(!['register-form','login-form','forgot-form','complete-form','modal-form','doc-form','profile-form'].includes(form.id))return;ev.preventDefault();
 if(['register-form','login-form','forgot-form','complete-form'].includes(form.id)){runAction(()=>authSubmit(form));return;}
 if(form.id==='modal-form'){runAction(()=>saveModal(form));return;}
 if(form.id==='doc-form'){runAction(()=>saveDocument(form,ev.submitter));return;}
 if(form.id==='profile-form'){runAction(()=>updateProfile(form));return;}
});
document.addEventListener('keydown',ev=>{const target=ev.target.closest('[data-state]');if(target&&(ev.key==='Enter'||ev.key===' ')){ev.preventDefault();selectedState=target.dataset.state;render();}});
document.addEventListener('visibilitychange',()=>{if(!document.hidden&&mode==='live'&&fb)loadAll().then(render).catch(console.error);});
init();
